      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ motivo })
    });
    const data = await res.json();
    await recargarFacturacion().catch(() => {});
    if (!res.ok) throw new Error(data.error || 'No se pudo anular la factura.');
    return data.factura;
  }

